entries[132120] = { ["name"] = "Einhüllender Nebel", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Schlangenstil\nHeilt das Ziel im Verlauf von 6 Sek. um 44449 und erhöht die Heilung, die das Ziel von Eurem Zauber 'Beruhigender Nebel' erhält, um 30%.\n\n'Einhüllender Nebel' wird zu einem Spontanzauber, wenn Ihr den Zauber wirkt, während Ihr 'Beruhigender Nebel' kanalisiert." }
