entries[132158] = { ["name"] = "Schnelligkeit der Natur", ["text"] = "Sofort 1 min Abklingzeit\nBei Aktivierung wird Euer nächstes Wirken von 'Wirbelsturm', 'Wucherwurzeln', 'Heilende Berührung', 'Winterschlaf', 'Pflege', 'Wiedergeburt' oder 'Nachwachsen' ein kostenloser Spontanzauber, der in allen Gestalten einsetzbar ist. Die Heilwirkung und Dauer des jeweiligen Zaubers ist um 50% erhöht. [ Wildheit : Kann nicht in Arenen oder auf Schlachtfeldern eingesetzt werden ]" }
