entries[132167] = { ["name"] = "Glyphe 'Blackout-Tritt'", ["text"] = "Wirken in 3 sek. 3\nTools: Schreibzeug des Virtuosen\nReagenzien:\nLeichtes Pergament , Meerestinte (3)\nGeringe Glyphe\nKlassen: Mönch\n25\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nEure Fähigkeit 'Blackout-Tritt' verursacht immer im Verlauf von 4 Sek. 20% zusätzlichen Schaden, ungeachtet der Position, doch Ihr könnt den Heileffekt nicht mehr auslösen." }
entries[132168] = { ["name"] = "Schockwelle", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchickt Euch eine Druckwelle voraus, die in einem kegelförmigen Bereich von 10 Metern [ Kampferfahrung : (75 / 100 * Angriffskraft * 1.2) / (75 / 100 * Angriffskraft)] Schaden verursacht und alle betroffenen gegnerischen Ziele 4 Sek. lang betäubt.\n\nErleiden 3 oder mehr Ziele davon Schaden, wird die Abklingzeit des nächsten Einsatzes von 'Schockwelle' um 20 Sek. verringert." }
entries[132169] = { ["name"] = "Sturmblitz", ["text"] = "30 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nSchleudert Eure Waffe nach einem Gegner, fügt ihm 125% Waffenschaden zu und betäubt das Ziel 4 Sek. lang. Verursacht 500% Waffenschaden gegen Ziele, die permanent immun gegen Betäubungseffekte sind." }
