entries[132302] = { ["name"] = "Wilde Attacke", ["text"] = "5 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nVerleiht abhängig von der Gestalt eine Bewegungsfähigkeit:\n\nHumanoid\nFliegt zur Position eines Verbündeten.\n\nBärengestalt\nStürmt auf einen Gegner zu und macht ihn 4 Sek. lang bewegungsunfähig.\n\nKatzengestalt\nSpringt hinter einen Gegner und macht ihn 3 Sek. lang benommen.\n\nMondkingestalt\nSpringt rückwärts.\n\nReisegestalt\nSpringt 20 Meter vorwärts.\n\nWassergestalt\nErhöht Euer Schwimmtempo 5 Sek. lang um zusätzlich 150%." }
entries[132303] = { ["name"] = "Kaskade", ["text"] = "10% von Grundmana 40 Meter Reichweite\nSofort 25 sek. Abklingzeit\nSchleudert dem Ziel eine heilige Kugel entgegen, die zunehmend stärker wird und Gegnern ( 12592 * 0.4) bis 12592 Heiligschaden zufügt oder Verbündete um ( 12592 * 0.4) bis 12592 heilt.\n\nDieser Effekt kann entweder von Verbündetem zu Verbündetem springen oder von Gegner zu Gegner. Mit jedem Sprung teilt sich die Kugel in 2 Kugeln auf, die weiter entfernte Ziele bevorzugen und nie das gleiche Ziel zweimal treffen. 'Kaskade' kann bis zu 4-mal springen.\n\nVerursacht in Schattengestalt Schattenschaden oder Heilung." }
