entries[132403] = { ["name"] = "Schild der Rechtschaffenen", ["text"] = "Nahkampfreichweite\nSofort\nVerpasst dem Ziel sofort einen heftigen Schlag mit Eurem Schild, der 836 Heiligschaden verursacht. Außerdem wird 3 Sek. lang Euer erlittener körperlicher Schaden um (25 *- 1 ; Min 30, Max 80)% verringert und der Effekt 'Bastion der Herrlichkeit' hervorgerufen.\n\nBastion der Herrlichkeit\nErhöht die Heilwirkung Eures nächsten Wirkens von [ Ewige Flamme : 'Ewige Flamme' / 'Wort der Herrlichkeit'], wenn der Zauber auf Euch selbst gewirkt wird, um 10%. [ Selbstloser Heiler : 'Selbstloser Heiler' erhöht ebenfalls Eure Selbstheilung mit 'Lichtblitz' um 20% pro Stapel ] Bis zu 5-mal stapelbar." }
entries[132404] = { ["name"] = "Schildblock", ["text"] = "Sofort\nHebt Euren Schild und blockt 6 Sek. lang jeden eintreffenden Nahkampfangriff. Dieses Blocken kann einen kritischen Effekt erzielen.\n\nMaximal 2 Aufladungen." }
