entries[132409] = { ["name"] = "Zaubersperre", ["text"] = "2% von Grundmana 40 Meter Reichweite\nSofort 24 sek. Abklingzeit\nBringt den Gegner 3 Sek. lang zum Schweigen. Wirkt das Ziel gerade einen Zauber, wird ein Gegenzauber gewirkt und 6 Sek. lang verhindert, dass erneut ein Zauber dieser Art gewirkt werden kann." }
entries[132410] = { ["name"] = "Verfolgung", ["text"] = "2% von Grundmana 8 - 25 Meter Reichweite\nSofort 15 sek. Abklingzeit\nStürmt auf einen Gegner zu, verursacht 100% Waffenschaden und erhöht das Bewegungstempo [ Grimoire der Überlegenheit : des Zornwächters / der Teufelswache] 6 Sek. lang um 30%.\n\nAutomatisches Wirken:\nWird immer eingesetzt, wenn [ Grimoire der Überlegenheit : der Zornwächter / die Teufelswache] weiter als 8 Meter vom Ziel entfernt ist.\n\n(Mit Rechtsklick umschalten)" }
entries[132411] = { ["name"] = "Magie versengen", ["text"] = "3% von Grundmana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nBrennt schädigende Magie aus dem Ziel heraus und entfernt 1 schädlichen Zauber von einem Verbündeten." }
entries[132412] = { ["name"] = "Verführung", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerführt das Ziel und verhindert dadurch bis zu 30 Sek. lang alle Aktionen. Jeglicher erlittene Schaden wird den Effekt aufheben. Funktioniert nur gegen Humanoide.\n\nAutomatisches Wirken:\nWird auf Ziele gewirkt, die den Meister betäuben, zum Schweigen bringen oder in Furcht versetzen.\n\n(Mit Rechtsklick umschalten)" }
