entries[132463] = { ["name"] = "Chiwelle", ["text"] = "Unbegrenzte Reichweite\nSofort\nIhr lasst eine Welle aus Chienergie durch Verbündete und Gegner fließen, die [ 493 + 1 * (Angriffskraft) * 0.45 * 1 ] Naturschaden oder [ 493 + (Angriffskraft) * 0.45] Heilung verursacht. Springt bis zu 7-mal auf die nächsten Ziele innerhalb von 25 Metern über.\n\nWenn die Welle auf Verbündete überspringt, bevorzugt sie dabei verwundete gegenüber vollständig gesunden Zielen." }
